-- New settings use German on deDE and English as the fallback on other clients.
local de = GetLocale() == "deDE";
TargetCharmsSettingsText = {};
local function text(key, english, german)
    TargetCharmsSettingsText[key] = de and german or english;
end
text("targets", "Target icons", "Zielmarker");
text("world", "World markers", "Weltmarker");
text("ready", "Ready check", "Bereitschaftscheck");
text("profiles", "Profiles & help", "Profile & Hilfe");
text("intro", "Choose a toolbar. Changes apply immediately. Configure outside combat.", "Leiste auswählen. Änderungen wirken sofort. Außerhalb des Kampfes konfigurieren.");
text("visibility", "Visibility & controls", "Sichtbarkeit & Bedienung");
text("enabled", "Show toolbar", "Leiste anzeigen");
text("enabledHelp", "Show or hide this toolbar independently. Disabled toolbars stay invisible even while settings are open. Your layout is preserved.", "Diese Leiste einzeln ein- oder ausblenden. Ausgeschaltete Leisten bleiben auch bei offenen Einstellungen unsichtbar. Deine Anordnung bleibt erhalten.");
text("toolbarVisibility", "Show / hide toolbars", "Leisten ein-/ausblenden");
text("group", "Only in a party / raid", "Nur in Gruppe / Schlachtzug");
text("groupHelp", "Target and world markers: in a raid, requires leader or assistant. Ready check: requires a group and leader or assistant.", "Ziel- und Weltmarker: im Schlachtzug nur als Leiter oder Assistent. Bereitschaftscheck: nur mit Gruppe und als Leiter oder Assistent.");
text("targetOnly", "Only with a target", "Nur mit ausgewähltem Ziel");
text("targetHelp", "Automatically hide the target toolbar when you have no target, including during combat.", "Zielmarkerleiste ohne ausgewähltes Ziel automatisch ausblenden, auch im Kampf.");
text("draggable", "Show move handle", "Verschiebegriff anzeigen");
text("dragHelp", "Drag the four-arrow handle with the left mouse button to move this toolbar. The same control is used on all three toolbars. Moving is available outside combat. Ctrl + right-click opens settings.", "Den Vier-Pfeile-Griff mit der linken Maustaste ziehen, um diese Leiste zu verschieben. Alle drei Leisten werden gleich bedient. Verschieben ist außerhalb des Kampfes möglich. Strg + Rechtsklick öffnet die Einstellungen.");
text("toggle", "Click again to clear target icon", "Erneut klicken entfernt den Zielmarker");
text("toggleHelp", "Clicking the same target icon again removes it instead of setting it again.", "Ein weiterer Klick auf denselben Zielmarker entfernt ihn wieder.");
text("overlays", "Show symbols on world markers", "Symbole auf Weltmarkern anzeigen");
text("overlayHelp", "Add the matching raid icon to each colored world-marker button.", "Zeigt das passende Schlachtzugsymbol auf den farbigen Weltmarker-Schaltflächen.");
text("appearance", "Size & appearance", "Größe & Darstellung");
text("scale", "Size", "Größe");
