text("arrangement", "Arrangement", "Anordnung");
text("columns", "Columns", "Spalten");
text("columnsHelp", "Icons per row. Rows are calculated automatically. Moving this slider converts the current arrangement into a grid and keeps its icons.", "Icons pro Zeile. Die Zeilen ergeben sich automatisch. Beim Bewegen wird die aktuelle Anordnung als Raster angeordnet; ihre Icons bleiben erhalten.");
text("horizontal", "Horizontal", "Horizontal");
text("vertical", "Vertical", "Vertikal");
text("grid", "3 columns", "3 Spalten");
text("original", "Original", "Original");
text("alternate", "Alternate preset", "Alternative Vorlage");
text("alternateHelp", "Target icons: inverted original layout. World markers: classic layout.", "Zielmarker: umgekehrte Original-Anordnung. Weltmarker: klassische Anordnung.");
